        if len(rows) < 2:
            continue
        top, bottom = min(rows), max(rows)
        if not all(g[r][c] == 5 for r in range(top, bottom + 1)):
            continue
        if c + 1 >= w:
            continue
        seed_rows = []
        r = bottom
        while r >= top and any(g[r][cc] != 0 for cc in range(c + 1, w)):
            seed_rows.insert(0, [g[r][cc] for cc in range(c + 1, w)])
            r -= 1
        if not seed_rows:
            continue
        start = bottom - len(seed_rows) + 1
        for rr in range(top, bottom + 1):
            pat = seed_rows[(rr - start) % len(seed_rows)]
            for cc in range(c + 1, w):
                if g[rr][cc] == 0 and pat[cc - c - 1] != 0:
                    g[rr][cc] = pat[cc - c - 1]

    # For each horizontal 5 segment, extend a colored vertical seed
    # below its left edge horizontally until a vertical 5 boundary.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            left = c
            while c + 1 < w and g[r][c + 1] == 5:
                c += 1
            right = c
